def running_maxima(values):
    if len(values) == 0:
        return []
    best = values[0]
    result = []
    for value in values:
        if value > best:
            best = value
        result.append(best)
    return result

print(running_maxima([]))
print(running_maxima([-4, -2, -5]))
print(running_maxima([3, 3, 1]))
